From 50dc5c8bfaa4a620d203e5a19b2bdd2b123c649e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:46:04 +0100
Subject: [PATCH] applets/digital-clock: add option to hide AM/PM in 12-hour
 mode

The clock could only show 12-hour time with AM/PM after it, which takes
space in the panel. Add a "Show AM/PM" checkbox below the time display
option; when unchecked, the panel shows the 12-hour time without it.

BUG: 507156
---
 applets/digital-clock/DigitalClock.qml     | 22 ++++++++++++++++++++--
 applets/digital-clock/configAppearance.qml |  8 ++++++++
 applets/digital-clock/main.xml             |  4 ++++
 3 files changed, 32 insertions(+), 2 deletions(-)

diff --git a/applets/digital-clock/DigitalClock.qml b/applets/digital-clock/DigitalClock.qml
index 8c918109d0..d5aa887c0d 100644
--- a/applets/digital-clock/DigitalClock.qml
+++ b/applets/digital-clock/DigitalClock.qml
@@ -132,6 +132,10 @@ MouseArea {
         function onShowSecondsChanged() {
             main.setupLabels();
         }
+
+        function onShowAmPmChanged() {
+            main.setupLabels();
+        }
     }

     function pointToPixel(pointSize: int): int {
@@ -431,7 +435,7 @@ MouseArea {
                 }
                 minimumPixelSize: 1

-                text: Qt.locale().toString(clock.dateTime, Plasmoid.configuration.showSeconds === 2 ? main.timeFormatWithSeconds : main.timeFormat)
+                text: main.formatLabelTime(clock.dateTime)
                 textFormat: Text.PlainText

                 verticalAlignment: Text.AlignVCenter
@@ -552,6 +556,16 @@ MouseArea {
         setupLabels();
     }

+    function formatLabelTime(dateTime: date): string {
+        const format = Plasmoid.configuration.showSeconds === 2 ? main.timeFormatWithSeconds : main.timeFormat;
+        const text = Qt.locale().toString(dateTime, format);
+        if (Plasmoid.configuration.showAmPm || !format.endsWith(" AP")) {
+            return text;
+        }
+        // Without AP, Qt shows 24-hour time, so drop the AM/PM text instead
+        return text.slice(0, -Qt.locale().toString(dateTime, " AP").length);
+    }
+
     function setupLabels() {
         const showTimezone = Plasmoid.configuration.showLocalTimezone
             || (Plasmoid.configuration.lastSelectedTimezone !== "Local"
@@ -597,7 +611,11 @@ MouseArea {
             }
         }
         // replace all placeholders with the widest number (two digits)
-        const format = (Plasmoid.configuration.showSeconds === 2 ? main.timeFormatWithSeconds : main.timeFormat).replace(/(h+|m+|s+)/g, "" + maximumWidthNumber + maximumWidthNumber); // make sure maximumWidthNumber is formatted as string
+        let format = Plasmoid.configuration.showSeconds === 2 ? main.timeFormatWithSeconds : main.timeFormat;
+        if (!Plasmoid.configuration.showAmPm) {
+            format = format.replace(/ AP$/, "");
+        }
+        format = format.replace(/(h+|m+|s+)/g, "" + maximumWidthNumber + maximumWidthNumber); // make sure maximumWidthNumber is formatted as string
         // build the time string twice, once with an AM time and once with a PM time
         const date = new Date(2000, 0, 1, 1, 0, 0);
         const timeAm = Qt.formatTime(date, format);
diff --git a/applets/digital-clock/configAppearance.qml b/applets/digital-clock/configAppearance.qml
index bcab974d18..0393451fff 100644
--- a/applets/digital-clock/configAppearance.qml
+++ b/applets/digital-clock/configAppearance.qml
@@ -43,6 +43,7 @@ KCMUtils.SimpleKCM {
     property string cfg_dateFormat: "shortDate"
     property alias cfg_customDateFormat: customDateFormat.text
     property alias cfg_use24hFormat: use24hFormat.currentIndex
+    property alias cfg_showAmPm: showAmPm.checked
     property alias cfg_dateDisplayFormat: dateDisplayFormat.currentIndex

     property real comboBoxWidth: Math.max(dateDisplayFormat.implicitWidth,
@@ -174,6 +175,13 @@ KCMUtils.SimpleKCM {
             }
         }

+        QQC2.CheckBox {
+            id: showAmPm
+            enabled: use24hFormat.currentIndex === 0
+                || (use24hFormat.currentIndex === 1 && Qt.locale().timeFormat(Locale.ShortFormat).toLowerCase().indexOf("ap") !== -1)
+            text: i18nc("@option:check", "Show AM/PM")
+        }
+
         Item {
             Kirigami.FormData.isSection: true
         }
diff --git a/applets/digital-clock/main.xml b/applets/digital-clock/main.xml
index 6716b906c5..137baf9725 100644
--- a/applets/digital-clock/main.xml
+++ b/applets/digital-clock/main.xml
@@ -91,6 +91,10 @@
       <label>Force the clock to use 12/24 hour time, instead of following the user locale.</label>
       <default>1</default>
     </entry>
+    <entry name="showAmPm" type="Bool">
+      <label>Whether the clock shows AM/PM when it uses 12 hour time.</label>
+      <default>true</default>
+    </entry>
     <entry name="firstDayOfWeek" type="Int">
       <label>Force the calendar to use a specific week day as first day of a week. -1 means follow user locale, 0 is Sunday, 1 is Monday, etc.</label>
       <default>-1</default>
-- 
